import heapq


def _dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        constraints = {name: [tuple(bounds)] for name, bounds in data["roots"].items()}
        best = None
        best_versions = None
        names = sorted(packages, reverse=(name_order == "descending"))

        def acyclic(chosen):
            edges = {}
            for name, row in chosen.items():
                edges[name] = [dep["name"] for dep in row.get("deps", [])
                               if (not dep.get("feature") or dep["feature"] in features)]
            done, active = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                for other in edges.get(name, []):
                    if not visit(other):
                        return False
                active.remove(name)
                done.add(name)
                return True

            return all(visit(name) for name in edges)

        def search(chosen, required):
            nonlocal best, best_versions
            for name, ranges in required.items():
                if name in chosen:
                    version = chosen[name]["version"]
                    if any(not low <= version <= high for low, high in ranges):
                        return

            pending = [name for name in required if name not in chosen]
            if not pending:
                if not acyclic(chosen):
                    return
                versions = {name: row["version"] for name, row in chosen.items()}
                vector = tuple(versions.get(name, -1) for name in names)
                if best is None or ((vector < best) if preference == "minimum" else (vector > best)):
                    best, best_versions = vector, versions
                return

            name = pending[0]
            ranges = required[name]
            rows = [row for row in packages[name]
                    if all(low <= row["version"] <= high for low, high in ranges)
                    and row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
            for row in rows:
                next_chosen = dict(chosen)
                next_chosen[name] = row
                next_required = {key: list(value) for key, value in required.items()}
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    next_required.setdefault(dep["name"], []).append((dep["min"], dep["max"]))
                search(next_chosen, next_required)

        search({}, constraints)
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}

    return solve


def _ledger_solver(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "half_up":
            return (2 * numerator + 10000) // 20000
        return numerator // 10000

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _quota_solver(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    eligible = [job for job in jobs if job["id"] not in blocked]
    if k > len(eligible):
        return {"error": "impossible"}

    best_ids = None
    best_value = None
    for subset in combinations(eligible, k):
        ids = sorted(job["id"] for job in subset)
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and ids < best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _route_solver(data):
    required = data.get("required", [])
    bit = {node: 1 << index for index, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    start_mask = bit.get(start_node, 0)
    start_state = (start_node, start_mask, data["coupons"])
    start_time = data["start"]
    distance = {start_state: start_time}
    queue = [(start_time, start_node, start_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distance.get(state) != arrival:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, remaining - 1))
            for duration, next_remaining in choices:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if next_time < distance.get(next_state, float("inf")):
                    distance[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask, next_remaining))
    return {"arrival": None}


